EVENT_SQL = '\nCREATE FUNCTION askanu_v7_event_metadata_valid(source_name TEXT, metadata_value JSONB)\nRETURNS BOOLEAN\nLANGUAGE plpgsql\nIMMUTABLE\nSTRICT\nAS $$\nDECLARE\n    field_name TEXT;\nBEGIN\n    IF source_name = \'rubric_unified_search\' THEN\n        RETURN askanu_v6_event_metadata_valid(metadata_value);\n    END IF;\n    IF source_name <> \'events_anu_official\' THEN RETURN FALSE; END IF;\n    IF jsonb_typeof(metadata_value) <> \'object\'\n       OR NOT metadata_value ?& ARRAY[\'entity_type\', \'source_event_id\', \'start_at\']\n       OR metadata_value - ARRAY[\n    \'entity_type\', \'source_event_id\', \'start_at\', \'end_at\', \'timezone\',\n    \'organiser_name\', \'venue_name\', \'address\', \'latitude\', \'longitude\',\n    \'category\', \'tags\', \'registration_url\', \'source_status\',\n    \'cancellation_status\', \'audience\', \'start_date\', \'end_date\', \'date_precision\'\n] <> \'{}\'::jsonb\n       OR metadata_value ->> \'entity_type\' <> \'event\'\n       OR jsonb_typeof(metadata_value -> \'source_event_id\') NOT IN (\'string\', \'null\')\n       OR btrim(metadata_value ->> \'source_event_id\') = \'\'\n       OR jsonb_typeof(metadata_value -> \'start_at\') NOT IN (\'string\', \'null\')\n       OR metadata_value ->> \'start_at\' !~\n          \'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2}([.][0-9]+)?)?(Z|[+-][0-9]{2}:[0-9]{2})$\'\n       OR (metadata_value ? \'end_at\'\n           AND jsonb_typeof(metadata_value -> \'end_at\') NOT IN (\'string\', \'null\'))\n       OR (jsonb_typeof(metadata_value -> \'end_at\') = \'string\'\n           AND metadata_value ->> \'end_at\' !~\n             \'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2}([.][0-9]+)?)?(Z|[+-][0-9]{2}:[0-9]{2})$\')\n       OR (jsonb_typeof(metadata_value -> \'timezone\') = \'string\'\n           AND metadata_value ->> \'timezone\' !~\n             \'^[A-Za-z_+-]+(/[A-Za-z0-9_+-]+)+$\')\n       OR (metadata_value ? \'latitude\'\n           AND jsonb_typeof(metadata_value -> \'latitude\') NOT IN (\'number\', \'null\'))\n       OR (metadata_value ? \'longitude\'\n           AND jsonb_typeof(metadata_value -> \'longitude\') NOT IN (\'number\', \'null\'))\n       OR (metadata_value ? \'tags\'\n           AND jsonb_typeof(metadata_value -> \'tags\') NOT IN (\'array\', \'null\'))\n       OR (jsonb_typeof(metadata_value -> \'tags\') = \'array\'\n           AND jsonb_path_exists(metadata_value, \'$.tags[*] ? (@.type() != "string")\'))\n       OR (metadata_value ? \'audience\'\n           AND jsonb_typeof(metadata_value -> \'audience\') NOT IN (\'string\', \'array\', \'null\'))\n       OR (jsonb_typeof(metadata_value -> \'audience\') = \'array\'\n           AND jsonb_path_exists(metadata_value, \'$.audience[*] ? (@.type() != "string")\'))\n    THEN\n        RETURN FALSE;\n    END IF;\n\n    FOREACH field_name IN ARRAY ARRAY[\n        \'timezone\', \'organiser_name\', \'venue_name\', \'address\', \'category\',\n        \'registration_url\', \'source_status\', \'cancellation_status\'\n    ]\n    LOOP\n        IF metadata_value ? field_name\n           AND jsonb_typeof(metadata_value -> field_name) NOT IN (\'string\', \'null\')\n        THEN\n            RETURN FALSE;\n        END IF;\n        IF jsonb_typeof(metadata_value -> field_name) = \'string\'\n           AND btrim(metadata_value ->> field_name) = \'\'\n        THEN\n            RETURN FALSE;\n        END IF;\n    END LOOP;\n\n    IF (jsonb_typeof(metadata_value -> \'tags\') = \'array\' AND EXISTS (\n        SELECT 1 FROM jsonb_array_elements_text(metadata_value -> \'tags\') value\n        WHERE btrim(value) = \'\'\n    )) OR (jsonb_typeof(metadata_value -> \'audience\') = \'array\' AND EXISTS (\n        SELECT 1 FROM jsonb_array_elements_text(metadata_value -> \'audience\') value\n        WHERE btrim(value) = \'\'\n    )) OR (jsonb_typeof(metadata_value -> \'audience\') = \'string\'\n           AND btrim(metadata_value ->> \'audience\') = \'\')\n    THEN\n        RETURN FALSE;\n    END IF;\n\n    IF metadata_value ->> \'start_at\' IS NULL THEN\n        IF metadata_value ->> \'date_precision\' IS DISTINCT FROM \'date\'\n           OR metadata_value ->> \'start_date\' IS NULL\n           OR metadata_value ->> \'end_at\' IS NOT NULL THEN RETURN FALSE; END IF;\n    ELSIF metadata_value ? \'date_precision\'\n          AND metadata_value ->> \'date_precision\' IS DISTINCT FROM \'timestamp\' THEN\n        RETURN FALSE;\n    END IF;\n    FOREACH field_name IN ARRAY ARRAY[\'start_date\', \'end_date\'] LOOP\n        IF metadata_value ->> field_name IS NOT NULL THEN\n            IF jsonb_typeof(metadata_value -> field_name) <> \'string\'\n               OR metadata_value ->> field_name !~ \'^[0-9]{4}-[0-9]{2}-[0-9]{2}$\'\n               OR to_char((metadata_value ->> field_name)::date, \'YYYY-MM-DD\') <> metadata_value ->> field_name THEN\n                RETURN FALSE;\n            END IF;\n        END IF;\n    END LOOP;\n    IF metadata_value ->> \'end_date\' IS NOT NULL AND\n       (metadata_value ->> \'start_date\' IS NULL OR\n        (metadata_value ->> \'end_date\')::date < (metadata_value ->> \'start_date\')::date) THEN RETURN FALSE; END IF;\n    IF metadata_value ->> \'start_at\' IS NOT NULL AND metadata_value ->> \'start_date\' IS NOT NULL AND\n       ((metadata_value ->> \'start_at\')::timestamptz AT TIME ZONE \'Australia/Canberra\')::date <> (metadata_value ->> \'start_date\')::date THEN RETURN FALSE; END IF;\n    IF metadata_value ->> \'end_at\' IS NOT NULL AND metadata_value ->> \'end_date\' IS NOT NULL AND\n       ((metadata_value ->> \'end_at\')::timestamptz AT TIME ZONE \'Australia/Canberra\')::date <> (metadata_value ->> \'end_date\')::date THEN RETURN FALSE; END IF;\n    RETURN TRUE;\nEXCEPTION WHEN OTHERS THEN\n    RETURN FALSE;\nEND;\n$$\n'

